import re

from django.db import migrations, models

# Valeur d'un OBX de type FIC : « SYSLAM64~WAACRP_….PDF~ACROBAT ».
FICHIER = re.compile(r"^[^~]*~([^~]+\.pdf)(~|$)", re.IGNORECASE)


def lignes_fichier_en_compte_rendu(apps, schema_editor):
    """Les résultats reçus avant ce changement portent le compte rendu comme
    une ligne de résultat : elle devient le nom du PDF attendu."""
    ResultatAnalyse = apps.get_model('laboratoire', 'ResultatAnalyse')
    for ligne in ResultatAnalyse.objects.filter(valeur__icontains='.pdf').select_related('analyse'):
        trouve = FICHIER.match(ligne.valeur)
        if not trouve:
            continue
        analyse = ligne.analyse
        if not analyse.compte_rendu_nom:
            analyse.compte_rendu_nom = trouve.group(1)
            analyse.save(update_fields=['compte_rendu_nom'])
        ligne.delete()


